long Fib(int n)
{
    long a = 0, b = 1;
    for (var i = 0; i < n; i++)
    {
        (a, b) = (b, a + b);
    }
    return a;
}

int Gcd(int a, int b)
{
    while (b != 0)
    {
        (a, b) = (b, a % b);
    }
    return a;
}

bool IsPrime(int n)
{
    if (n < 2)
    {
        return false;
    }
    for (var i = 2; i * i <= n; i++)
    {
        if (n % i == 0)
        {
            return false;
        }
    }
    return true;
}

long Factorial(int n)
{
    long result = 1;
    for (var i = 2; i <= n; i++)
    {
        result *= i;
    }
    return result;
}

Console.WriteLine($"fib(10) = {Fib(10)}");
Console.WriteLine($"gcd(54, 24) = {Gcd(54, 24)}");

var primes = Enumerable.Range(2, 48).Where(IsPrime).ToList();
Console.WriteLine("primes: " + string.Join(" ", primes));

var squares = Enumerable.Range(1, 19).Select(n => n * n).ToList();
Console.WriteLine($"index of 144: {squares.BinarySearch(144)}");
Console.WriteLine($"10! = {Factorial(10)}");

